```cuda
template <typename scalar_t>
__global__ __launch_bounds__(512)
void rmsnorm_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    scalar_t* __restrict__ output,
    int hidden_size,
    float eps
) {
    int row = blockIdx.x;
    const scalar_t* x = input + row * hidden_size;
    scalar_t* o = output + row * hidden_size;

    constexpr int VEC = 8;
    int num_vec = hidden_size / VEC;

    extern __shared__ float smem[];
    float* s_val = smem;
    float* s_w = smem + hidden_size;
    float* s_shared = smem + 2 * hidden_size;
    float* s_rms_inv_ptr = s_shared + 32;

    float sum_sq = 0.0f;

    for (int i = threadIdx.x; i < num_vec; i += blockDim.x) {
        uint4 xv = *reinterpret_cast<const uint4*>(&x[i * VEC]);
        uint4 wv = *reinterpret_cast<const uint4*>(&weight[i * VEC]);
        const scalar_t* xs = reinterpret_cast<const scalar_t*>(&xv);
        const scalar_t* ws = reinterpret_cast<const scalar_t*>(&wv);
        #pragma unroll
        for (int j = 0; j < VEC; j++) {
            float val = static_cast<float>(xs[j]);
            float w = static_cast<float>(ws[j]);
            s_val[i * VEC + j] = val;
            s_w[i * VEC + j] = w;
            sum_sq += val * val;
        }
    }
    for (int i = num_vec * VEC + threadIdx.x; i < hidden_size; i += blockDim.x) {
        float val = static_cast<float>(__ldg(&x[i]));
        float w = static_cast<float>(__ldg(&weight[i]));
        s_val[i] = val;
        s_w[i] = w;
        sum_sq += val * val;
    }

    for (int offset = warpSize / 2; offset > 0; offset >>= 1)
        sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);

    int lane = threadIdx.x & 31;
    int warp_id = threadIdx.x >> 5;

    if (lane == 0) s_shared[warp_id] = sum_sq;
    __syncthreads();

    if (warp_id == 0) {
        int num_warps = (blockDim.x + 31) >> 5;
        sum_sq = (lane < num_warps) ? s_shared[lane] : 0.0f;
        for (int offset = warpSize / 2; offset > 0; offset >>= 1)
            sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);
    }

    if (threadIdx.x == 0) {
        *s_rms_inv_ptr = rsqrtf(sum_sq / hidden_size + eps);
    }
    __syncthreads();

    float rms_inv = *s_rms_inv_ptr;

    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        o[i] = static_cast<scalar_t>(s_val[i] * rms_inv * s_w[i]);
    }
}
```

